    83→						+ "([0-9]+)"
    84→					+ ")"
    85→					+ "([.][0-9]+)*"
    86→				+ ")"
    87→			+ "){0,1}" //없거나 한번등장
    88→			+ "$" //규칙끝 (뒷공백 없음)
    89→		);
