    91→	public static final char[] AVAIL_SYMBOLS_INNUMBER = new char[] {
    92→		// 예외특수문자, 숫자에 사용이 가능한 기호들
    93→		// 아래 항목이 바뀌는 경우 숫자와 관련된 정규식도 같이 바뀌어야 함
    94→		',', '.', SYMBOL_COLON };
    95→
    96→	public static final char[] AVAIL_SYMBOLS_SPLIT = new char[] {
    97→		// 단어사이에 구분자로 올 수 있는 기호들, 사용자단어에 들어가는 기호는 삭제해야 한다.
