   414→
   415→	public static String isSplit(char c) {
   416→		String ret = getType(c);
   417→		if (ret == WHITESPACE || ret == SYMBOL) {
   418→			return ret;
   419→		} else if (ret == SYMBOL && (containsChar(AVAIL_SYMBOLS_SPLIT, c) || (c > 128))) {
   420→			// unicode 특수문자는 모두 구분자로 사용한다.
   421→			return ret;
   422→		}
   423→		return null;
   424→	}
   425→
   426→	public static String getUniType(CharSequence cv) {
   427→		String ret = null;
   428→		String prevType = null;
   429→		String type = null;
   430→		for (int inx = 0; inx < cv.length(); inx++) {
   431→			prevType = type;
   432→			type = getType(cv.charAt(inx));
   433→			if (prevType != null && type != prevType) {
   434→				if (prevType != type) {
   435→					type = UNCATEGORIZED;
   436→					break;
   437→				}
   438→			}
   439→		}
   440→		ret = type;
   441→		return ret;
   442→	}
   443→
   444→	public static boolean isAlphaNum(CharVector cv) {
   445→		boolean ret = true;
   446→		if (cv.length() == 0) {
   447→			return false;
   448→		}
   449→		for (int inx = 0; inx < cv.length(); inx++) {
   450→			String type = ProductNameTokenizer.getType(cv.array()[cv.offset() + inx]);
   451→			if (!(type == ProductNameTokenizer.ALPHA || type == ProductNameTokenizer.NUMBER)) {
   452→				ret = false;
   453→				break;
   454→			}
   455→		}
   456→		return ret;
   457→	}
   458→
   459→	public static String getTermType(CharSequence cv) {
   460→		String ret = null;
   461→		String prevType = null;
   462→		String type = null;
   463→		for (int inx = 0; inx < cv.length(); inx++) {
   464→			prevType = type;
   465→			type = getType(cv.charAt(inx));
   466→			// logger.trace("TYPE:{} / {}", type, cv);
   467→			if (prevType != null && type != prevType) {
   468→				if ((prevType == ALPHA && type == NUMBER) || (prevType == NUMBER && type == ALPHA)) {
   469→					type = ALPHANUM;
   470→				} else if (prevType == ALPHANUM && (type == ALPHA || type == NUMBER)) {
   471→					type = ALPHANUM;
   472→				} else if ((prevType == ALPHA && type == SYMBOL) || (prevType == NUMBER && type == SYMBOL)
   473→						|| (prevType == ALPHANUM && type == SYMBOL)) {
   474→					type = ASCII;
   475→				} else if (prevType == ASCII && (type == ALPHA || type == NUMBER || type == SYMBOL)) {
   476→					type = ASCII;
   477→				} else {
   478→					type = UNCATEGORIZED;
   479→				}
   480→			} else {
   481→
   482→			}
   483→			// logger.trace("TYPE:{} / PREV:{}", type, prevType);
   484→		}
   485→		ret = type;
   486→		return ret;
   487→	}
   488→
   489→	public static String getType(int ch) {
   490→		if(Character.isWhitespace(ch)){
   491→			return WHITESPACE;
   492→		}
   493→		
   494→		int type = Character.getType(ch);
   495→		
   496→		switch(type){
   497→		case Character.DASH_PUNCTUATION:
   498→		case Character.START_PUNCTUATION:
   499→		case Character.END_PUNCTUATION:
   500→		case Character.CONNECTOR_PUNCTUATION:
   501→		case Character.OTHER_PUNCTUATION:
   502→		case Character.MATH_SYMBOL:
   503→		case Character.CURRENCY_SYMBOL:
   504→		case Character.MODIFIER_SYMBOL:
   505→		case Character.OTHER_SYMBOL:
   506→		case Character.INITIAL_QUOTE_PUNCTUATION:
   507→		case Character.FINAL_QUOTE_PUNCTUATION:
   508→			return SYMBOL;
   509→		case Character.OTHER_LETTER:
   510→			//외국어.
   511→			Character.UnicodeBlock unicodeBlock = Character.UnicodeBlock.of(ch);
   512→			if (unicodeBlock == Character.UnicodeBlock.HANGUL_SYLLABLES){
   513→				return HANGUL;
   514→			} else if (unicodeBlock == Character.UnicodeBlock.HANGUL_COMPATIBILITY_JAMO) {
   515→				return HANGUL_JAMO;
   516→			} else if (unicodeBlock == Character.UnicodeBlock.HIRAGANA || unicodeBlock == Character.UnicodeBlock.KATAKANA) {
   517→				return JAPANESE;
   518→			} else if (unicodeBlock == Character.UnicodeBlock.CJK_UNIFIED_IDEOGRAPHS) {
   519→				return CHINESE;
   520→			}else{
   521→				return OTHER_LANGUAGE;
   522→			}
   523→		case Character.UPPERCASE_LETTER:
   524→		case Character.LOWERCASE_LETTER:
   525→			//영어.
   526→			return ALPHA;
   527→			
   528→		case Character.DECIMAL_DIGIT_NUMBER:
   529→			return NUMBER;
   530→		}
   531→		
   532→		return UNCATEGORIZED;
   533→	}
   534→}

