package com.danawa.search.analysis.product.action;

import org.elasticsearch.client.internal.node.NodeClient;
import org.elasticsearch.rest.BaseRestHandler;
import org.elasticsearch.rest.RestRequest;
import org.elasticsearch.rest.RestStatus;
import org.elasticsearch.rest.action.RestToXContentListener;

import java.util.List;

import static org.elasticsearch.rest.RestRequest.Method.GET;
import static org.elasticsearch.rest.RestRequest.Method.POST;

/**
 * 사전 리로드 REST API 핸들러
 *
 * <p>클러스터 전체 노드에 사전 리로드 명령을 전파하는 REST 엔드포인트입니다.</p>
 *
 * <h3>API 엔드포인트:</h3>
 * <ul>
 *   <li>POST /_analysis-product-name/reload-dict - 클러스터 전체 리로드</li>
 *   <li>GET /_analysis-product-name/reload-dict - 상태 확인 겸 리로드</li>
 * </ul>
 *
 * <h3>파라미터:</h3>
 * <ul>
 *   <li>type - 사전 타입 (SYNONYM, USER, COMPOUND 등)</li>
 * </ul>
 */
public class RestReloadDictAction extends BaseRestHandler {

    @Override
    public String getName() {
        return "reload_dict_action";
    }

    @Override
    public List<Route> routes() {
        return List.of(
            new Route(POST, "/_analysis-product-name/reload-dict"),
            new Route(GET, "/_analysis-product-name/reload-dict")
        );
    }

    @Override
    protected RestChannelConsumer prepareRequest(RestRequest request, NodeClient client) {
        // 파라미터 파싱
        String type = request.param("type");

        // NodesRequest 생성
        ReloadDictNodesRequest nodesRequest = new ReloadDictNodesRequest(type);

        // ES 9.1.2: RestToXContentListener 사용 (ToXContentObject 응답용)
        return channel -> client.execute(
            TransportReloadDictAction.TYPE,
            nodesRequest,
            new RestToXContentListener<>(channel, r -> r.isAllSuccessful() ? RestStatus.OK : RestStatus.MULTI_STATUS)
        );
    }
}

