   638→	// 랭킹뷰어, 관리도구에서 사용되는 동의어 확장용 메소드
   639→	private static List<CharSequence> getAnalyzeSynonym(String combineTerm, boolean useforQuery) {
   640→		TokenStream analyzerStream;
   641→		List<CharSequence> synonyms;
   642→		List<CharSequence> result = new ArrayList<>();
   643→
   644→		// 동의어 확장
