   647→			SynonymAttribute synAtr = analyzerStream.addAttribute(SynonymAttribute.class);
   648→			TypeAttribute typeAttr = analyzerStream.addAttribute(TypeAttribute.class);
   649→
   650→			analyzerStream.reset();
   651→			while (analyzerStream.incrementToken()){
   652→				if ((synonyms = synAtr.getSynonyms()) != null && synonyms.size() > 0) {
   653→					for (CharSequence synonym : synonyms) {
   654→						String type = typeAttr.type();
