  1297→			.key("result").array();
  1298→
  1299→		List<TagProb> tagProbs = productNameDictionary.find(CharVector.valueOf(word));
  1300→		for (int inx = 0;tagProbs != null && inx < tagProbs.size(); inx++) {
  1301→			TagProb tagProb = tagProbs.get(inx);
  1302→			builder.object()
  1303→				.key(ES_DICT_FIELD_TYPE).value("SYSTEM")
  1304→				.key(ES_DICT_FIELD_KEYWORD).value(word)
  1305→				.key("posTag").value(tagProb.posTag())
  1306→				.key("prob").value(tagProb.prob())
