  1308→		}
  1309→		for (String type : keySet) {
  1310→			type = type.toUpperCase();
  1311→
  1312→			BoolQueryBuilder query = QueryBuilders.boolQuery()
  1313→				.must(QueryBuilders.matchQuery(ES_DICT_FIELD_TYPE, type))
