  1322→				CharVector value = CharVector.valueOf(data.get(ES_DICT_FIELD_VALUE));
  1323→				CharVector id = CharVector.valueOf(data.get(ES_DICT_FIELD_ID));
  1324→				builder.object();
  1325→				builder.key(ES_DICT_FIELD_TYPE).value(type);
  1326→				if (keyword != null && keyword.length() > 0) {
  1327→					builder.key(ES_DICT_FIELD_KEYWORD).value(keyword);
  1328→				}
  1329→				if (value != null && value.length() > 0) {
  1330→					builder.key(ES_DICT_FIELD_VALUE).value(value);
  1331→				}
  1332→				if (id != null && id.length() > 0) {
  1333→					builder.key(ES_DICT_FIELD_ID).value(id);
  1334→				}
  1335→				builder.endObject();
  1336→			}
  1337→		}
